function PreDownloadHomeDialog:OnNextStory()
    if self.isFirstEnter then
        self.isFirstEnter = false
        local finishID = PreDownloadUtils.GetParamsVoValue(PreDownloadConstants.ParamsNewKey.QUESTIONS_STORY_ENTER_PART_TWO_ID)
        local firstEnterStoryInfo = PreDownloadUtils.GetStoryInfo(finishID)
        local enterStoryInfo = firstEnterStoryInfo
        if #enterStoryInfo > 0 then
            self:PlayStory(1, enterStoryInfo, nil, function()
                CfUtils.WriteLocalData(self:GetCacheKeyByUserId(Constants.PlayerPrefsType.PreDownloadStoryOpening), '1')
                self:OnFinishStory()
            end)
        end
    else
        ----已经播过剧情了
        self:OnFinishStory()
    end
end

