function PreDownloadHomeDialog:FreshTouchAction()
    local pro = 0
    local max = table.count(self.touchState)
    for _, v in pairs(self.touchState) do
        if v.isFinish then
            pro = pro + 1
        end
    end
    print('==>>', pro, max)
    CfUtils.FillText(self.BtnInteraction:Find("Text/TxtNum"), string.format('<color=#FF009C><size=32>%d</size></color>/%d', pro, max))
    CfUtils.FillText(self.TouchTips.transform:Find("Title1/TxtDeco/TxtNum"), string.format('<color=#FF009C><size=32>%d</size></color>/%d', pro, max))
    local nodes = {
        self.TouchTips:Find("hair"),
        self.TouchTips:Find("chest"),
        self.TouchTips:Find("skirt"),
        self.TouchTips:Find("tail"),
    }
    for i, node in pairs(nodes) do
        local data = self.touchState[i]
        if data then
            local isFinish = checkBool(data.isFinish)
            CfUtils.SetActive(node:Find("ImgBg"), isFinish)
            if not isFinish then
                CfUtils.FillText(node:Find("Txttitle"), "？？？")
            else
                CfUtils.FillText(node:Find("Txttitle"), data.name)
            end
            CfUtils.SetUISwitchImage(node:Find("ImgIcon"), isFinish and 1 or 2)
        else
            CfUtils.SetActive(node, false)
        end
    end
end

