--region init
function PreDownloadHomeDialog:InitHandler()
    CfUtils.SetActive(self.BtnEmotionTest, false)
    self.handler = Events.AddListener(Constants.EventNames.PreDownloadDataUpdate, function()
        self:InitView()
    end)
    self.touchEventHandler = Events.AddListener(IdolLive3D_States.EventPlayAction, function(event)
        --点击部分情况下的逻辑
        xTry(function()
            local eventKey = event.key
            local prefixKey = string.split(eventKey, '_')[1]
            if self.touchState2Index[prefixKey] then
                local index = self.touchState2Index[prefixKey]
                self.touchState[index].isFinish = true
                local t = {}
                for i, v in pairs(self.touchState) do
                    t[tostring(v.id)] = v.isFinish
                end
                CfUtils.WriteLocalData(self:GetCacheKeyByUserId(PreDownloadProgressState), table.serialize(t))
            end
            print("==>>", event)
            if self.isFirstEnter and string.find(eventKey, 'TouchHead_') then
                ---点击头的情况下处理
                CfUtils.StartCoroutineWithBlocker(function()
                    xTry(function()
                        coroutine.yield(CoYield(0.5))
                        self:ShowInteractionClickTips(false)
                        self:FreshTouchAction() --刷新状态
                        CfUtils.SetActive(self.BtnEmotionTest, false)
                        CfUtils.SetActive(self.Container:Find("UIFX_StartBoom"), true)
                        CfUtils.SetActive(self.Container:Find("UIFX_Number_BoomMove"), true)
                        self.Container:Find("UIFX_Number_BoomMove").transform:DOMove(self.BtnInteraction.transform.position, 0.5)
                        coroutine.yield(CoYield(0.5))
                        CfUtils.SetActive(self.Container:Find("UIFX_StartBoom"), false)
                        CfUtils.SetActive(self.Container:Find("UIFX_Number_BoomMove"), false)
                        CfUtils.SetActive(self.BtnInteraction.transform.parent, true)
                        CfUtils.SetActive(self.BtnInteraction, true)
                        CfUtils.SetActive(self.Container:Find("UIFX_EndBoom"), true)
                        coroutine.yield(CoYield(2))
                        CfUtils.SetActive(self.BtnInteraction.transform.parent, false)
                        CfUtils.SetActive(self.BtnInteraction, false)
                        CfUtils.SetActive(self.Container:Find("UIFX_EndBoom"), false)
                        CfUtils.SetActive(self.BtnEmotionTest, true)
                        self:OnNextStory() ---开始第二段对白剧情
                    end)
                end)
            else
                ---其他交互事件的逻辑
                self:FreshTouchAction()
            end
        end)
    end)
    SetButtonAction(self.BtnEmotionTest, Bind(self, self.BtnEmotionTestClickHandler))
    SetButtonAction(self.BtnInteraction, Bind(self, self.BtnInteractionClickHandler))
    self.BtnHdModeAnimationTF = self.BtnHdMode.transform:Find("Animation")
    SetButtonAction(self.BtnHdMode, function()
        ---设置高清模式的逻辑
        self.isGraphicHD = not self.isGraphicHD
        if self.isGraphicHD == true then
            xRecord.record('14-028', 'change_type_on')
            if isNotNull(self.idolLive3D_GraphicSetting) then
                self.idolLive3D_GraphicSetting:TurnOn()
            end
            CfUtils.PlayAnimation(self.BtnHdModeAnimationTF, "IdolLive3D_MainUI_High_Open")

            IdolLive3D_Utils.SetPlanarReflections(false)
            IdolLive3D_Utils.SetPlanarReflections(true)

        else
            xRecord.record('14-028', 'change_type_off')
            if isNotNull(self.idolLive3D_GraphicSetting) then
                self.idolLive3D_GraphicSetting:TurnOff()
            end
            CfUtils.PlayAnimation(self.BtnHdModeAnimationTF, "IdolLive3D_MainUI_High_Closed")

            IdolLive3D_Utils.SetPlanarReflections(false)
            IdolLive3D_Utils.SetPlanarReflections(true)

        end
        CfUtils.PlayAnimation(self.BtnHdMode, "UI_Common_ButtonPressed")
    end)

    ---设置做题按钮的事件
    local agreeScore = PreDownloadUtils.GetParamsVoValue(PreDownloadConstants.ParamsNewKey.QUESTIONS_AGREE)
    local disAgreeScore = PreDownloadUtils.GetParamsVoValue(PreDownloadConstants.ParamsNewKey.QUESTIONS_DIS_AGREE)
    ---@type Game.Native.Common.ID
    local idComponent = KTool.GetOrAddComponent(self.optionNode:Find("Btn00").gameObject, typeof(ID))
    idComponent.id = 0
    SetButtonAction(self.optionNode:Find("Btn00"), function()
        self:OnQuestionChoice_("Btn00")
    end)
    local t = string.split(agreeScore, ';')
    for i, v in pairs(t) do
        local store = checkNumber(v)
        local nodeKey = 'BtnBlue0' .. (#t - i + 1)
        local nodeTrans = self.optionNode:Find(nodeKey)
        ---@type Game.Native.Common.ID
        idComponent = KTool.GetOrAddComponent(nodeTrans.gameObject, typeof(ID))
        idComponent.id = store
        SetButtonAction(nodeTrans, function()
            self:OnQuestionChoice_(nodeKey)
        end)
    end
    t = string.split(disAgreeScore, ';')
    for i, v in pairs(t) do
        local store = -checkNumber(v)
        local nodeKey = 'BtnRed0' .. i
        local nodeTrans = self.optionNode:Find(nodeKey)
        ---@type Game.Native.Common.ID
        idComponent = KTool.GetOrAddComponent(nodeTrans.gameObject, typeof(ID))
        idComponent.id = store
        SetButtonAction(nodeTrans, function()
            self:OnQuestionChoice_(nodeKey)
        end)
    end
end

---GetCacheKeyByUserId
---获取与用户关联关系的存储key值
---@param storeKey string
function PreDownloadHomeDialog:GetCacheKeyByUserId(storeKey)
    ---@type UserComponent
    local userComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.UserComponent)
    if userComponent then
        local userId = userComponent.userInfo.userId
        storeKey = storeKey .. tostring(userId)
    end
    return storeKey
end

function PreDownloadHomeDialog:InitData(hasRequest)
    if isNull(hasRequest) then
        hasRequest = true
    end
    self.testQuestions_ = {}
    -- check questions cache
    local testQuestionsCache = CfUtils.GetLocalData(self:GetCacheKeyByUserId(Constants.PlayerPrefsType.PreDownloadTestQuestions), '')
    if not string.isEmpty(testQuestionsCache) then
        -- load questions cache
        self.testQuestions_ = table.deserialize(testQuestionsCache)
        -- check question index
        for questionIndex, questionData in ipairs(self.testQuestions_) do
            if checkNumber(questionData.choiceId) == DefaultChoiceStore then
                self.questionIndex_ = questionIndex
                break
            end
        end

        -- done question
        if self:GetQuestionIndex() == 0 then
            self.questionIndex_ = #self.testQuestions_
        end

    else
        ---@type PreDownloadTestQuestionVo[]
        local allQuestionConf = CfUtils.GetWholeVo(AutoIds.IdSetting3103, 'PreDownloadTestQuestionVo')
        -- init questions data
        for confIndex, questionVo in ipairs(allQuestionConf) do
            self.testQuestions_[confIndex] = {
                questionId = questionVo.id,
                choiceId = DefaultChoiceStore,
            }
        end
        -- save questions cache
        self:SaveTestQuestionsCache_()

        -- reset question index
        self.questionIndex_ = 1
    end
    if hasRequest then
        PreDownloadMgr:UpdatePreDownloadData()
    end
end

function PreDownloadHomeDialog:InitView()
    CfUtils.SetActive(self.BtnEmotionTest, true)
    self.TextDesc:Init()
end

