function PreDownloadHomeDialog:OnTestResultAction()
    SetButtonAction(self.ResultNode:Find("Btnresetting"), function()
        GameUtils.SecondConfirm(localize('是否要重新测试？'), function()
            CfUtils.SetActive(self.ResultNode, false)
            CfUtils.SetActive(self.Black, false)
            CfUtils.SetActive(self.Fuzzy, false)
            CfUtils.SetActive(self.optionNode, true)
            self:InitData(false)
            self:BtnEmotionTestClickHandler()
            CfUtils.PlayAnimation(self.optionNode, "PredownloadEntryMainDialog_optionNodeGo")
        end, nil, nil, 4)
    end)
    local preDownloadComp = PreDownloadMgr:GetPreDownloadComponent()
    local testResultId = preDownloadComp:GetMmpiResultId()
    ---@type PreDownloadTestResultVo
    local testResultConf = CfUtils.GetCfVo(AutoIds.IdSetting3101, "PreDownloadTestResultVo", testResultId)
    CfUtils.FillImage(self.ResultNode:Find("ImgCat"), testResultConf.catHead)
    CfUtils.FillText(self.ResultNode:Find("TxtTilte"), testResultConf.title)
    CfUtils.FillText(self.ResultNode:Find("DescNode/TxtCatDesc"), testResultConf.result)
    CfUtils.FillText(self.ResultNode:Find("TxtTilte/TxtCat"), testResultConf.catTitle)
    CfUtils.FillText(self.ResultNode:Find("TextDescScrollView/Viewport/Content/TextDesc"), testResultConf.desc)
end
