function PreDownloadHomeDialog:HandleBackAction()
    self.isTesting = false
    CfUtils.SetTopCommonActive(false, false)
    CfUtils.SetActive(self.OptionDesc, false)
    CfUtils.SetActive(self.ResultNode, false)
    CfUtils.SetActive(self.Black, false)
    CfUtils.SetActive(self.Fuzzy, false)
    CfUtils.SetActive(self.optionNode, false)
    CfUtils.SetActive(self.BtnInteraction.transform.parent, true)
    local dialogEnv = UIModule.CurrentScreen:GetDialog(Constants.UITypeIds.PreDownloadLoadHintDialog)
    if dialogEnv and dialogEnv.Env then
        dialogEnv.Env:SetNewPlayerUIState(true)
    end
    if not self:IsSimple() then
        if IdolLive3D_States.isPlayingTimeline ~= true then
            IdolLive3D_States.LeaveFreeze()
        end
        IdolLive3D_States.MoveToState( IdolLive3D_States.GameInstaller.farFreeCameraParams )
    end
end

function PreDownloadHomeDialog:OnCloseResultView()
    CfUtils.SetTopCommonActive(false, false)
    self.isTesting = false
    local dialogEnv = UIModule.CurrentScreen:GetDialog(Constants.UITypeIds.PreDownloadLoadHintDialog)
    if dialogEnv and dialogEnv.Env then
        dialogEnv.Env:SetNewPlayerUIState(true)
    end
    CfUtils.SetActive(self.ResultNode, false)
    CfUtils.SetActive(self.Black, false)
    CfUtils.SetActive(self.Fuzzy, false)
    CfUtils.SetActive(self.optionNode, false)
    CfUtils.SetActive(self.OptionDesc, false)
    CfUtils.SetActive(self.BtnInteraction.transform.parent, true)
    if not self:IsSimple() then
        if IdolLive3D_States.isPlayingTimeline ~= true then
            IdolLive3D_States.LeaveFreeze()
        end
    end
end

function PreDownloadHomeDialog:ShowTestResult()
    local preDownloadComp = PreDownloadMgr:GetPreDownloadComponent()
    local testQuestionsCache = CfUtils.GetLocalData(self:GetCacheKeyByUserId(Constants.PlayerPrefsType.PreDownloadTestQuestions), '')
    if checkInt(preDownloadComp:GetMmpiResultId()) > 0 and string.isEmpty(testQuestionsCache) then
        ---测试结果展示
        CfUtils.SetActive(self.ResultNode, true)
        CfUtils.SetActive(self.Black, true)
        CfUtils.SetActive(self.Fuzzy, true)
        CfUtils.SetActive(self.optionNode, false)
        CfUtils.SetActive(self.OptionDesc, false)
        CfUtils.SetTopCommonActive(false, false)
        self:OnTestResultAction()
    end
end
