---情绪测试按钮点击回调
function PreDownloadHomeDialog:BtnEmotionTestClickHandler()
    if IdolLive3D_States.isPlayingTimeline then
        return
    end
    self.isTesting = true
    xRecord.record('14-019', "click_test")
    CfUtils.SetActive(self.BtnInteraction.transform.parent.gameObject, false)
    local dialogEnv = UIModule.CurrentScreen:GetDialog(Constants.UITypeIds.PreDownloadLoadHintDialog)
    if dialogEnv and dialogEnv.Env then
        dialogEnv.Env:SetNewPlayerUIState(false, true)
    end
    if IdolLive3D_States.isPlayingTimeline ~= true then
        IdolLive3D_States.EnterFreeze(IdolLive3D_States.GameInstaller.tgtFreeCameraParams)
    end

    local preDownloadComp = PreDownloadMgr:GetPreDownloadComponent()
    local testQuestionsCache = CfUtils.GetLocalData(self:GetCacheKeyByUserId(Constants.PlayerPrefsType.PreDownloadTestQuestions), '')
    if checkInt(preDownloadComp:GetMmpiResultId()) > 0 and string.isEmpty(testQuestionsCache) then
        ---测试结果展示
        self:ShowTestResult()
    else
        ---做题界面的逻辑
        CfUtils.SetActive(self.ResultNode, false)
        --- 1.先播开头的剧情说话的逻辑，然后再显示做题界面,已播放过开头的剧情
        local firstEnterId = PreDownloadUtils.GetParamsVoValue(PreDownloadConstants.ParamsNewKey.OPENING_STORY_FIRST_TIME_ID)
        local startStoryId = PreDownloadUtils.GetParamsVoValue(PreDownloadConstants.ParamsNewKey.QUESTIONS_STORY_BEGIN_ID)
        local firstEnterStoryInfo = PreDownloadUtils.GetStoryInfo(firstEnterId)
        local startStoryInfo = PreDownloadUtils.GetStoryInfo(startStoryId)
        local isPlayedStory = CfUtils.GetLocalData(self:GetCacheKeyByUserId(Constants.PlayerPrefsType.PreDownloadStoryTestEnter), '') == '1'
        local enterStoryInfo = {}
        local questIndex = self:GetQuestionIndex()
        if questIndex > 1 then
            startStoryInfo = {}
        end
        self.hasEnter = false
        if not isPlayedStory and #firstEnterStoryInfo > 0 then
            ---未播过开始做题时的剧情时，先剧情
            for i, v in pairs(startStoryInfo) do
                table.insert(firstEnterStoryInfo, v)
            end
            enterStoryInfo = firstEnterStoryInfo
            self.hasEnter = true
        else
            enterStoryInfo = startStoryInfo
        end
        if #enterStoryInfo > 0 and questIndex == 1 then
            self:PlayStory(1, enterStoryInfo, function(item, startIndex)
                if self.hasEnter and startIndex >= #firstEnterStoryInfo then
                    ---第一次进入答题需要播放的剧情
                    CfUtils.WriteLocalData(self:GetCacheKeyByUserId(Constants.PlayerPrefsType.PreDownloadStoryTestEnter), '1')
                end
            end, function()
                CfUtils.SetActive(self.OptionDesc, true)
                CfUtils.SetActive(self.TextNum, true)
                CfUtils.SetActive(self.TextDeco, true)
                CfUtils.SetActive(self.Slider, true)
                CfUtils.SetActive(self.optionNode, true)
                self:UpdateTestProgress_()
                self:SetQuestionIndex(self:GetQuestionIndex())
                CfUtils.SetTopCommonActive(true, false)
            end)
        else
            ---非第一题的情况下，直接进入签题界面
            CfUtils.SetActive(self.OptionDesc, true)
            CfUtils.SetActive(self.TextNum, true)
            CfUtils.SetActive(self.TextDeco, true)
            CfUtils.SetActive(self.Slider, true)
            CfUtils.SetActive(self.optionNode, true)
            self:UpdateTestProgress_()
            self:SetQuestionIndex(self:GetQuestionIndex())
            CfUtils.SetTopCommonActive(true, false)
        end
    end
end

function PreDownloadHomeDialog:PlayStory(startIndex, storyInfo, onStepper, onFinish)
    local function FillText(item)
        if not item then
            return
        end
        if onStepper then
            onStepper(item, startIndex)
        end
        -- update question title
        local txtContent = self.TextDesc
        txtContent:ResetArgs()
        txtContent:SetText("")
        txtContent.PendingTime = 0.02
        txtContent.AppearDuration = 0.35
        txtContent.IgnoreTimeScale = true
        txtContent.TextWillFill = item.desc
        CfUtils.StartCoroutineWithBlocker(function()
            xTry(function()
                coroutine.yield(txtContent:StartType())
                coroutine.yield(CoYield(1.2))
                startIndex = startIndex + 1
                if startIndex > #storyInfo then
                    if onFinish then
                        onFinish() ---播放完成了
                    end
                else
                    item = storyInfo[startIndex]
                    FillText(item)
                end
            end)
        end)
    end

    if not CfUtils.IsActive(self.OptionDesc) then
        CfUtils.SetActive(self.OptionDesc, true)
        CfUtils.SetActive(self.TextNum, false)
        CfUtils.SetActive(self.TextDeco, false)
        CfUtils.SetActive(self.Slider, false)
        --SetButtonAction(self.ImgBg, function()
        --    print("====>>>", startIndex)
        --    ---点中时进行下一句的显示
        --    startIndex = startIndex + 1
        --    if startIndex > #storyInfo then
        --        if onFinish then
        --            onFinish() ---播放完成了
        --        end
        --    else
        --        local item = storyInfo[startIndex]
        --        FillText(item)
        --    end
        --end)
    end
    local item = storyInfo[startIndex]
    FillText(item)
end

