-----答题相关-----
function PreDownloadHomeDialog:GetQuestionIndex()
    return checkNumber(self.questionIndex_)
end

---UpdateTestProgress_
---设置答题进度值
function PreDownloadHomeDialog:UpdateTestProgress_()
    local questionData = self.testQuestions_[self:GetQuestionIndex()] or {}
    local isChoiceDone = checkInt(questionData.choiceId) ~= DefaultChoiceStore
    local questionCount = self:GetQuestionIndex() - (isChoiceDone and 0 or 1)

    -- update progress text
    local questionTotal = #self.testQuestions_
    local progress = string.format_color_tag(string.format_size_tag(questionCount, 32), "#d2d2d2")
    CfUtils.FillText(self.TextNum, string.format('%s/%d', progress, questionTotal))
    CfUtils.SetSliderPercent(self.Slider, (questionCount / questionTotal))
    CfUtils.FillText(self.TextDesc, questionData.desc)
end

function PreDownloadHomeDialog:SetQuestionIndex(value)
    self.questionIndex_ = checkInt(value)
    self:UpdateTestQuestions_()
end

function PreDownloadHomeDialog:UpdateTestQuestions_()
    local questionData = self.testQuestions_[self:GetQuestionIndex()] or {}
    ---@type PreDownloadTestQuestionVo
    local questionConf = CfUtils.GetCfVo(AutoIds.IdSetting3103, 'PreDownloadTestQuestionVo', questionData.questionId)
    ---设置答题数据信息,以及答题进度
    -- update question title
    local txtContent = self.TextDesc
    txtContent:ResetArgs()
    txtContent:SetText("")
    txtContent.PendingTime = 0.02
    txtContent.AppearDuration = 0.2
    txtContent.IgnoreTimeScale = true
    txtContent.TextWillFill = questionConf.question
    txtContent:StartType()
end

function PreDownloadHomeDialog:SaveTestQuestionsCache_()
    local testQuestionsCache = ''
    if self.testQuestions_ then
        testQuestionsCache = table.serialize(self.testQuestions_)
    end
    CfUtils.WriteLocalData(self:GetCacheKeyByUserId(Constants.PlayerPrefsType.PreDownloadTestQuestions), testQuestionsCache)
end

---@param nodeKey string
function PreDownloadHomeDialog:OnQuestionChoice_(nodeKey)
    local nodeTrans = self.optionNode:Find(nodeKey)
    CfUtils.SetActive(nodeTrans:Find("ImgGetDeco"), true)
    ---@type Game.Native.Common.ID
    local idComponent = KTool.GetComponent(nodeTrans.gameObject, typeof(ID))
    local store = checkNumber(idComponent.id)
    CfUtils.StartCoroutineWithBlocker(function()
        xTry(function()
            coroutine.yield(WaitForSecondsRealtime(0.8))
            CfUtils.PlayDelayShowAnimation(self.optionNode, 1, "PredownloadEntryMainDialog_optionNodeGo", "PredownloadEntryMainDialog_optionNodeOut")
            CfUtils.PlayDelayShowAnimation(self.OptionDesc, 1, "PredownloadEntryMainDialog_optionNodeOptionDescGo", "PredownloadEntryMainDialog_optionNodeOptionDescOut")
            coroutine.yield(WaitForSecondsRealtime(0.45))
            CfUtils.SetActive(nodeTrans:Find("ImgGetDeco"), false)
            -- update question choice
            local questionData = self.testQuestions_[self:GetQuestionIndex()] or {}
            questionData.choiceId = store
            self:SaveTestQuestionsCache_()
            local questionTotal = #self.testQuestions_
            local allChoiceDone = self:GetQuestionIndex() == questionTotal
            if allChoiceDone then
                self:UpdateTestProgress_()
                -- request result
                self:ToRequestTestRequest_()
            else
                -- next question
                self:SetQuestionIndex(self:GetQuestionIndex() + 1)
                self:UpdateTestProgress_()
            end
        end)
    end)
end

function PreDownloadHomeDialog:ToRequestTestRequest_()
    local scoreDict = {}
    for _, questionData in ipairs(self.testQuestions_) do
        local choiceStore = checkNumber(questionData.choiceId)
        local choiceId = questionData.questionId
        ---@type PreDownloadTestQuestionVo
        local questionConf = CfUtils.GetCfVo(AutoIds.IdSetting3103, 'PreDownloadTestQuestionVo', questionData.questionId)
        local t = {}
        if choiceStore >= 0 then
            t.choiceYes = questionConf.choiceYes
            t.scoreYes = choiceStore
            t.choiceNo = questionConf.choiceNo
            t.scoreNo = 0
        else
            t.choiceYes = questionConf.choiceYes
            t.scoreYes = 0
            t.choiceNo = questionConf.choiceNo
            t.scoreNo = math.abs(choiceStore)
        end
        scoreDict[tostring(choiceId)] = t
    end
    CfUtils.SetActive(self.OptionDesc, false)
    CfUtils.SetActive(self.TextNum, false)
    CfUtils.SetActive(self.TextDeco, false)
    CfUtils.SetActive(self.Slider, false)
    CfUtils.SetActive(self.optionNode, false)
    --if Config.DEBUG then
    --    -- update resultId
    --    local mmpiResultId = 17
    --    local preDownloadComp = PreDownloadMgr:GetPreDownloadComponent()
    --    preDownloadComp:SetMmpiResultId(mmpiResultId)
    --    local hideId = PreDownloadUtils.GetParamsVoValue(PreDownloadConstants.ParamsNewKey.QUESTIONS_HIDE_ID)
    --    if checkNumber(hideId) == mmpiResultId then
    --        --hide storyInfo
    --        local startStoryId = PreDownloadUtils.GetParamsVoValue(PreDownloadConstants.ParamsNewKey.QUESTIONS_STORY_HIDE_FINISH_ID)
    --        local finishStoryInfo = PreDownloadUtils.GetStoryInfo(startStoryId)
    --        if #finishStoryInfo > 0 then
    --            self:PlayStory(1, finishStoryInfo, nil, function()
    --                self:ShowTestResult()
    --            end)
    --        else
    --            self:ShowTestResult()
    --        end
    --    else
    --        --- 1.先播开头的剧情说话的逻辑，然后再显示做题界面,已播放过开头的剧情
    --        local finishStoryId = PreDownloadUtils.GetParamsVoValue(PreDownloadConstants.ParamsNewKey.QUESTIONS_STORY_FINISH_ID)
    --        local finishStoryInfo = PreDownloadUtils.GetStoryInfo(finishStoryId)
    --        --local startStoryInfo = PreDownloadUtils.GetStoryInfo(startStoryId)
    --        if #finishStoryInfo > 0 then
    --            self:PlayStory(1, finishStoryInfo, nil, function()
    --                self:ShowTestResult()
    --            end)
    --        else
    --            self:ShowTestResult()
    --        end
    --    end
    --end
    GameUtils.Request(Interfaces.PreDownloadMMPI, { score = table.serialize(scoreDict), userId = PreDownloadUtils.GetUserId() }, function(request, response)
        if checkInt(response.errCode) ~= 0 then
            return
        end
        xRecord.record('14-027', "click_finish")
        local preDownloadComp = PreDownloadMgr:GetPreDownloadComponent()
        -- update replayTimes
        local mmpiReplayTimes = preDownloadComp:GetMmpiReplayTimes()
        if checkInt(preDownloadComp:GetMmpiResultId()) > 0 then
            preDownloadComp:SetMmpiReplayTimes(mmpiReplayTimes - 1)
        end
        -- clean questions cache
        CfUtils.WriteLocalData(self:GetCacheKeyByUserId(Constants.PlayerPrefsType.PreDownloadTestQuestions), '')
        CfUtils.SetTopCommonActive(false, false)
        local hideId = PreDownloadUtils.GetParamsVoValue(PreDownloadConstants.ParamsNewKey.QUESTIONS_HIDE_ID)
        -- update resultId
        local mmpiResultId = checkInt(response.data.mmpiId)
        if mmpiResultId <= 0 then
            print("====>>", mmpiResultId)
            mmpiResultId = hideId
        end
        preDownloadComp:SetMmpiResultId(mmpiResultId)
        if checkNumber(hideId) == mmpiResultId then
            --hide storyInfo
            local startStoryId = PreDownloadUtils.GetParamsVoValue(PreDownloadConstants.ParamsNewKey.QUESTIONS_STORY_HIDE_FINISH_ID)
            local finishStoryInfo = PreDownloadUtils.GetStoryInfo(startStoryId)
            if #finishStoryInfo > 0 then
                self:PlayStory(1, finishStoryInfo, nil, function()
                    self:OnLoadingResult()
                end)
            else
                self:OnLoadingResult()
            end
        else
            --- 1.先播开头的剧情说话的逻辑，然后再显示做题界面,已播放过开头的剧情
            local finishStoryId = PreDownloadUtils.GetParamsVoValue(PreDownloadConstants.ParamsNewKey.QUESTIONS_STORY_FINISH_ID)
            local finishStoryInfo = PreDownloadUtils.GetStoryInfo(finishStoryId)
            --local startStoryInfo = PreDownloadUtils.GetStoryInfo(startStoryId)
            if #finishStoryInfo > 0 then
                self:PlayStory(1, finishStoryInfo, nil, function()
                    self:OnLoadingResult()
                end)
            else
                self:OnLoadingResult()
            end
        end
    end)
end

function PreDownloadHomeDialog:OnLoadingResult()
    CfUtils.SetActive(self.Black, true)
    CfUtils.SetActive(self.Fuzzy, true)
    CfUtils.SetActive(self.Loading, true)
    CfUtils.StartCoroutineWithBlocker(function()
        xTry(function()
            coroutine.yield(CoYield(0.5))
            CfUtils.PlayAnimation(self.Loading, "PredownloadEntryMainDialog_Loading_End")
            coroutine.yield(CoYield(0.5))
            CfUtils.SetActive(self.Loading, false)
            self:ShowTestResult()
        end)
    end)
end


